import Foundation

/// The optional, version-bound artifact generated by the shared ledger engine.
struct ReleaseChanges: Decodable, Equatable {
    struct Change: Decodable, Equatable, Identifiable {
        let pr: Int
        let mergeSHA: String
        let delta: [String: Int]
        let fromVersion: String
        let toVersion: String
        let summary: String?
        var id: Int { pr }

        enum CodingKeys: String, CodingKey {
            case pr, delta, summary
            case mergeSHA = "merge_sha", fromVersion = "from_version", toVersion = "to_version"
        }
    }

    let schemaVersion: Int
    let repository: String
    let version: String
    let initialVersion: String
    let segments: [String]
    let changes: [Change]
    static let repositoryIdentity = "PinedaTec-EU/LeonardoMD"

    enum CodingKeys: String, CodingKey {
        case repository, version, segments, changes
        case schemaVersion = "schema_version", initialVersion = "initial_version"
    }

    enum InvalidArtifact: Error { case identity, history, summary }

    static func load(data: Data, packagedVersion: String) throws -> Self {
        let artifact = try JSONDecoder().decode(Self.self, from: data)
        try artifact.validate(packagedVersion: packagedVersion)
        return artifact
    }

    func validate(packagedVersion: String) throws {
        guard schemaVersion == 1, repository == Self.repositoryIdentity,
              version == packagedVersion, segments == ["release", "feature", "build"],
              let target = Self.parts(version), var running = Self.parts(initialVersion) else {
            throw InvalidArtifact.identity
        }
        var seen = Set<Int>()
        for change in changes {
            guard change.pr > 0, seen.insert(change.pr).inserted,
                  change.mergeSHA.range(of: "^[0-9a-f]{40}$", options: .regularExpression) != nil,
                  Self.parts(change.fromVersion) == running, !change.delta.isEmpty,
                  Set(change.delta.keys).isSubset(of: Set(segments)) else { throw InvalidArtifact.history }
            for (index, segment) in segments.enumerated() {
                if let amount = change.delta[segment] {
                    let result = running[index].addingReportingOverflow(amount)
                    guard amount > 0, !result.overflow else { throw InvalidArtifact.history }
                    running[index] = result.partialValue
                }
            }
            guard Self.parts(change.toVersion) == running else { throw InvalidArtifact.history }
            if let summary = change.summary {
                guard !summary.isEmpty, summary == summary.trimmingCharacters(in: .whitespacesAndNewlines),
                      summary.unicodeScalars.count <= 280,
                      !summary.unicodeScalars.contains(where: {
                          [.control, .lineSeparator, .paragraphSeparator].contains($0.properties.generalCategory)
                      }) else { throw InvalidArtifact.summary }
            }
        }
        guard running == target else { throw InvalidArtifact.history }
    }

    static func parts(_ version: String) -> [Int]? {
        let tokens = version.split(separator: ".", omittingEmptySubsequences: false)
        guard tokens.count == 3 else { return nil }
        var result: [Int] = []
        for token in tokens {
            guard token == "0" || (!token.hasPrefix("0") && token.allSatisfy({ $0.isASCII && $0.isNumber })),
                  let value = Int(token), value >= 0 else { return nil }
            result.append(value)
        }
        return result
    }

    func changes(after baseline: String?) -> [Change] {
        guard let baseline, let parts = Self.parts(baseline),
              let current = Self.parts(version), !current.lexicographicallyPrecedes(parts),
              baseline == initialVersion || changes.contains(where: { $0.toVersion == baseline }) else {
            return changes.reversed()
        }
        return changes.filter { change in
            guard let next = Self.parts(change.toVersion) else { return false }
            return parts.lexicographicallyPrecedes(next)
        }.reversed()
    }
}
